from pathlib import Path
import base64,hashlib,json,os,stat
payload=json.loads('{"SHA256SUMS": {"base64": "", "sha256": "4887e1a1ba0324bcb5c7feabd7ac294f3dea430b0782c21de0261ccbc7494ce2"}, "expected-inputs.json": {"base64": "", "sha256": "a1740c60f8d10890ad56f84cb8d5760cfa82a678c8bf4d7d2c8459a41eccac93"}, "attachment_hotfix.py": {"base64": "", "sha256": "2e13d1e2f508d6bdf06761fd5e830a795130dc01df4d4eb7e8dd2a6fb6301b34"}, "hr_agent_migrate.py": {"base64": "", "sha256": "381dbfbcf89bdc286dc1544982705f656ba9b1a0f2ba4442769f7498a56455b2"}, "preflight-execution-job-kind.sh": {"base64": "", "sha256": "88644e92079949a49e695474ab0c5d15e77cc238d13116e76db880f14d2e3b2e"}}')
parent=Path('/opt/orbbec-agent-platform/private')
p=parent.lstat()
if os.getuid()!=0 or parent.is_symlink() or not stat.S_ISDIR(p.st_mode) or p.st_uid!=0 or stat.S_IMODE(p.st_mode)!=0o700:raise RuntimeError('parent invalid')
for name in ['agent-brain-action.lock','deploy-input.lock']:
 if (parent/name).exists() or (parent/name).is_symlink():raise RuntimeError('active deployment')
if set(payload)!={'SHA256SUMS','expected-inputs.json','attachment_hotfix.py','hr_agent_migrate.py','preflight-execution-job-kind.sh'}:raise RuntimeError('bundle invalid')
for item in payload.values():
 if hashlib.sha256(base64.b64decode(item['base64'],validate=True)).hexdigest()!=item['sha256']:raise RuntimeError('input corrupt')
os.umask(0o077)
target=parent/'attachment-hotfix-inputs'
target.mkdir(mode=0o700,exist_ok=False)
receipt={}
for name,item in payload.items():
 data=base64.b64decode(item['base64'],validate=True)
 fd=os.open(target/name,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
 with os.fdopen(fd,'wb') as stream:
  stream.write(data);stream.flush();os.fsync(stream.fileno())
 state=(target/name).lstat()
 actual=hashlib.sha256((target/name).read_bytes()).hexdigest()
 if state.st_uid!=0 or stat.S_IMODE(state.st_mode)!=0o600 or actual!=item['sha256']:raise RuntimeError('installed file invalid')
 receipt[name]={'sha256':actual,'bytes':state.st_size,'mode':'0600','uid':state.st_uid}
fd=os.open(target,os.O_RDONLY|os.O_DIRECTORY);os.fsync(fd);os.close(fd)
print(json.dumps({'status':'installed_tool_inputs_only','target':str(target),'files':receipt,'services_changed':False,'migrations_run':False,'supervisor_invoked':False},indent=2))
